def int_to_roman(n):
    vals = [(1000, "M"), (500, "D"), (100, "C"), (50, "L"), (10, "X"), (5, "V"), (1, "I")]

    # Use a list of values sorted by magnitude, then use greedy approach with lookahead
    result = []
    for v, s in vals:
        count = 0
        while n >= v and count < 10:
